from nltk.tokenize import sent_tokenize
import re

def _score_sentence_pronoun_coverage(text: str) -> float:
    content = extract_content(text, 'pronoun_density')
    if not content:
        return 0.0
    sents = sent_tokenize(content)
    if not sents:
        return 0.0
    address = {'i','me','my','mine','myself','we','us','our','ours','ourselves','you','your','yours','yourself','yourselves'}
    has_address = any(
        any(re.search(r'\\b'+re.escape(p)+r'\\b', s.lower()) for p in address)
        for s in sents
    )
    they_family = {'they','them','their','theirs','themselves'}
    pronouns = {'he','him','his','himself','she','her','hers','herself'} | address
    if has_address:
        pronouns |= they_family
    hits = sum(1 for s in sents
               if any(re.search(r'\\b'+re.escape(p)+r'\\b', s.lower()) for p in pronouns))
    return hits / len(sents)
